SELECT * FROM payment_transactions


        AND (
        order_code ILIKE CONCAT('%', #{keyword}, '%')
        OR reference_id ILIKE CONCAT('%', #{keyword}, '%')
        OR external_transaction_id ILIKE CONCAT('%', #{keyword}, '%')
        OR provider ILIKE CONCAT('%', #{keyword}, '%')
        )


        AND status = #{status}


        AND provider = #{provider}


